const fs = require('fs');
const path = require('path');

function processDir(dir, type) {
    if (!fs.existsSync(dir)) return;
    const files = fs.readdirSync(dir);
    for (const file of files) {
        const fullPath = path.join(dir, file);
        if (fs.statSync(fullPath).isDirectory()) {
            processDir(fullPath, type);
        } else if (fullPath.endsWith('.jsx')) {
            let content = fs.readFileSync(fullPath, 'utf8');
            
            // Fix double imports generated by my previous PowerShell script
            content = content.replace(/import AdminLayout from '\.\.\/layouts\/AdminLayout';\nimport AdminLayout from '\.\.\/layouts\/AdminLayout';/g, "import AdminLayout from '../layouts/AdminLayout';");
            content = content.replace(/import CustomerLayout from '\.\.\/\.\.\/layouts\/CustomerLayout';\nimport CustomerLayout from '\.\.\/\.\.\/layouts\/CustomerLayout';/g, "import CustomerLayout from '../../layouts/CustomerLayout';");
            content = content.replace(/import CustomerLayout from '\.\.\/layouts\/CustomerLayout';\nimport CustomerLayout from '\.\.\/layouts\/CustomerLayout';/g, "import CustomerLayout from '../layouts/CustomerLayout';");
            
            // Remove old Layout and Sidebar imports
            content = content.replace(/import DashboardLayout from '.*?';?\r?\n?/g, '');
            content = content.replace(/import AdminSidebar from '.*?';?\r?\n?/g, '');
            content = content.replace(/import UserSidebar from '.*?';?\r?\n?/g, '');
            content = content.replace(/import Sidebar from '.*?';?\r?\n?/g, '');
            
            if (type === 'admin') {
                if (!content.includes('import AdminLayout')) {
                    const rel = path.relative(path.join(__dirname, 'resources/js/components/admin'), fullPath);
                    const depth = rel.split(path.sep).length - 1;
                    const prefix = depth > 0 ? '../'.repeat(depth) : './';
                    content = "import AdminLayout from '" + prefix + "../layouts/AdminLayout';\n" + content;
                }
                content = content.replace(/<DashboardLayout[\s\S]*?>/, '<AdminLayout title="Admin Dashboard">');
                content = content.replace(/<\/DashboardLayout>/g, '</AdminLayout>');
            } else if (type === 'customer') {
                if (!content.includes('import CustomerLayout')) {
                    const rel = path.relative(path.join(__dirname, 'resources/js/components/customer'), fullPath);
                    const depth = rel.split(path.sep).length - 1;
                    const prefix = depth > 0 ? '../'.repeat(depth) : './';
                    content = "import CustomerLayout from '" + prefix + "../layouts/CustomerLayout';\n" + content;
                }
                content = content.replace(/<DashboardLayout[\s\S]*?>/, '<CustomerLayout title="Customer Dashboard">');
                content = content.replace(/<\/DashboardLayout>/g, '</CustomerLayout>');
            }
            
            fs.writeFileSync(fullPath, content);
        }
    }
}

processDir(path.join(__dirname, 'resources/js/components/admin'), 'admin');
processDir(path.join(__dirname, 'resources/js/components/customer'), 'customer');
console.log('Script completed');
